package com.cpf.starter.notification.email;import com.cpf.starter.notification.*;import org.springframework.mail.MailException;import org.springframework.mail.SimpleMailMessage;import org.springframework.mail.javamail.JavaMailSender;
public final class CpfEmailNotificationProvider implements CpfNotificationProvider {private final JavaMailSender sender;private final String from;public CpfEmailNotificationProvider(JavaMailSender s,String f){sender=s;from=f;}public String channel(){return "EMAIL";}public CpfNotificationResult send(CpfNotificationRequest r){SimpleMailMessage m=new SimpleMailMessage();m.setFrom(from);m.setTo(r.recipient());m.setSubject(r.variables().getOrDefault("subject",r.templateId()));m.setText(r.variables().getOrDefault("body",""));try{sender.send(m);return CpfNotificationResult.sent(r.notificationId(),"SMTP",null);}catch(MailException ex){return CpfNotificationResult.unknown(r.notificationId(),"SMTP","SMTP acceptance is unknown: "+ex.getClass().getSimpleName());}}}
